import React, { useState } from "react";

export default function RegistroSolicitante() {
  const [formData, setFormData] = useState({
    nombre: "",
    correo: "",
    servicio: ""
  });
  const [mensaje, setMensaje] = useState("");
  const [errores, setErrores] = useState({});
  const [isLoading, setIsLoading] = useState(false);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
    // Limpiar error cuando el usuario empiece a escribir
    if (errores[name]) {
      setErrores({ ...errores, [name]: false });
    }
  };

  const validar = () => {
    const err = {};
    if (!formData.nombre.trim()) err.nombre = true;
    if (!formData.correo.trim()) err.correo = true;
    if (!formData.servicio) err.servicio = true;

    // Validar formato de email
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (formData.correo && !emailRegex.test(formData.correo)) {
      err.correo = true;
    }

    setErrores(err);
    return Object.keys(err).length === 0;
  };

  const sendSolicitud = async (e) => {
    if (!validar()) return;

    setIsLoading(true);

    // Simular llamada a API (reemplaza con tu axiosInstance)
    try {
      // await axiosInstance.post("/registro", formData);
      await new Promise(resolve => setTimeout(resolve, 1500)); // Simulación

      setMensaje("¡Solicitud enviada correctamente! Pronto será aprobada.");
      setFormData({ nombre: "", correo: "", servicio: "" });
      setErrores({});
    } catch (error) {
      setMensaje("Error al enviar la solicitud. Intenta nuevamente.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 via-gray-800 to-black flex items-center justify-center p-4">
      {/* Background decorativo */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        <div className="absolute -top-40 -right-40 w-80 h-80 bg-green-500 rounded-full opacity-10 blur-3xl"></div>
        <div className="absolute -bottom-40 -left-40 w-80 h-80 bg-blue-500 rounded-full opacity-10 blur-3xl"></div>
      </div>

      <div className="w-full max-w-md relative z-10">
        {/* Header Card */}
        <div className="bg-white rounded-t-2xl shadow-2xl">
          <div className="text-center py-8 px-6">
            <div className="mb-4">
              <div className="w-16 h-16 bg-gradient-to-br from-green-400 to-green-600 rounded-full mx-auto flex items-center justify-center shadow-lg">
                <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6v6m0 0v6m0-6h6m-6 0H6" />
                </svg>
              </div>
            </div>
            <h1 className="text-2xl font-bold text-gray-800 mb-2">¡Date a conocer!</h1>
            <p className="text-sm text-gray-600">¿DESEAS INSCRIBIRTE?</p>
            <div className="mt-4 inline-block bg-green-500 text-white px-4 py-2 rounded-full text-sm font-semibold shadow-lg">
              30% de descuento en la evaluación inicial
            </div>
          </div>
        </div>

        {/* Form Card */}
        <div className="bg-gradient-to-br from-green-500 to-green-600 rounded-b-2xl shadow-2xl p-8">
          <div className="mb-6 text-center text-white">
            <p className="text-sm opacity-90 mb-4">
              Ingrese su nombre, dirección de correo electrónico y selecciona en qué deseas recibir información y nos contactaremos con usted
            </p>

            {/* Features */}
            <div className="space-y-2 text-left">
              <div className="flex items-center text-sm">
                <svg className="w-4 h-4 mr-2 text-green-200" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                </svg>
                Datos Seguros
              </div>
              <div className="flex items-center text-sm">
                <svg className="w-4 h-4 mr-2 text-green-200" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                </svg>
                Interacción personal y segura
              </div>
              <div className="flex items-center text-sm">
                <svg className="w-4 h-4 mr-2 text-green-200" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                </svg>
                Comunicación Directa
              </div>
            </div>
          </div>

          <div className="space-y-4">
            {/* Campo Nombre */}
            <div className="space-y-1">
              <input
                type="text"
                name="nombre"
                className={`w-full px-4 py-3 rounded-xl border-0 focus:ring-4 focus:ring-white/30 focus:outline-none transition-all duration-300 ${
                  errores.nombre 
                    ? "bg-red-50 text-red-900 placeholder-red-400 ring-2 ring-red-500" 
                    : "bg-white text-gray-800 placeholder-gray-500"
                }`}
                placeholder="Ingrese su nombre"
                value={formData.nombre}
                onChange={handleInputChange}
              />
              {errores.nombre && (
                <p className="text-red-200 text-xs ml-2 flex items-center">
                  <svg className="w-3 h-3 mr-1" fill="currentColor" viewBox="0 0 20 20">
                    <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                  </svg>
                  El nombre es requerido
                </p>
              )}
            </div>

            {/* Campo Correo */}
            <div className="space-y-1">
              <input
                type="email"
                name="correo"
                className={`w-full px-4 py-3 rounded-xl border-0 focus:ring-4 focus:ring-white/30 focus:outline-none transition-all duration-300 ${
                  errores.correo 
                    ? "bg-red-50 text-red-900 placeholder-red-400 ring-2 ring-red-500" 
                    : "bg-white text-gray-800 placeholder-gray-500"
                }`}
                placeholder="Ingrese su correo electrónico"
                value={formData.correo}
                onChange={handleInputChange}
              />
              {errores.correo && (
                <p className="text-red-200 text-xs ml-2 flex items-center">
                  <svg className="w-3 h-3 mr-1" fill="currentColor" viewBox="0 0 20 20">
                    <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                  </svg>
                  Ingrese un correo válido
                </p>
              )}
            </div>

            {/* Campo Servicio */}
            <div className="space-y-1">
              <select
                name="servicio"
                className={`w-full px-4 py-3 rounded-xl border-0 focus:ring-4 focus:ring-white/30 focus:outline-none transition-all duration-300 ${
                  errores.servicio 
                    ? "bg-red-50 text-red-900 ring-2 ring-red-500" 
                    : "bg-white text-gray-800"
                }`}
                value={formData.servicio}
                onChange={handleInputChange}
              >
                <option value="">Seleccione un servicio</option>
                <option value="Terapias">Terapias</option>
                <option value="Terapias Integrales">Terapias Integrales</option>
                <option value="Material Virtual">Material Virtual</option>
                <option value="Material Físico">Material Físico</option>
              </select>
              {errores.servicio && (
                <p className="text-red-200 text-xs ml-2 flex items-center">
                  <svg className="w-3 h-3 mr-1" fill="currentColor" viewBox="0 0 20 20">
                    <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                  </svg>
                  Seleccione un servicio
                </p>
              )}
            </div>

            {/* Botón Enviar */}
            <button
              className={`w-full py-4 px-6 rounded-xl font-semibold text-white transition-all duration-300 transform hover:scale-105 focus:outline-none focus:ring-4 focus:ring-gray-300 ${
                isLoading 
                  ? "bg-gray-600 cursor-not-allowed" 
                  : "bg-gray-800 hover:bg-gray-700 active:scale-95 shadow-lg hover:shadow-xl"
              }`}
              onClick={sendSolicitud}
              disabled={isLoading}
            >
              {isLoading ? (
                <div className="flex items-center justify-center">
                  <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                  </svg>
                  Enviando...
                </div>
              ) : (
                "Enviar"
              )}
            </button>
          </div>

          {/* Mensaje de respuesta */}
          {mensaje && (
            <div className={`mt-6 p-4 rounded-xl text-center font-medium ${
              mensaje.includes("Error") 
                ? "bg-red-500/20 text-red-100 border border-red-400/30" 
                : "bg-white/20 text-white border border-white/30"
            }`}>
              <div className="flex items-center justify-center">
                {mensaje.includes("Error") ? (
                  <svg className="w-5 h-5 mr-2" fill="currentColor" viewBox="0 0 20 20">
                    <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                  </svg>
                ) : (
                  <svg className="w-5 h-5 mr-2" fill="currentColor" viewBox="0 0 20 20">
                    <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                  </svg>
                )}
                {mensaje}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
